package org.walkwithgod.community;import jakarta.persistence.*;import org.walkwithgod.common.BaseEntity;import org.walkwithgod.user.AppUser;import java.util.*;
@Entity @Table(name="reactions",uniqueConstraints=@UniqueConstraint(name="uk_reaction_user_post",columnNames={"user_id","post_id"})) public class Reaction extends BaseEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)private AppUser user;@ManyToOne(fetch=FetchType.LAZY,optional=false)private Post post;@Column(nullable=false,length=20)private String type;public AppUser getUser(){return user;}public void setUser(AppUser v){user=v;}public Post getPost(){return post;}public void setPost(Post v){post=v;}public String getType(){return type;}public void setType(String v){type=v;}}
